a<-commandArgs(TRUE);p<-a[1];s<-read.csv(file.path(p,'summary.csv'));d<-subset(s,type=='gate_effect_on_threshold' & metric=='population1000');labels<-c('48 fixed','96 fixed','48 staggered','96 staggered');young<-d[match(paste('young',labels),d$label),];old<-d[match(paste('old',labels),d$label),];stopifnot(!anyNA(young$mean),!anyNA(old$mean));png(file.path(p,'age-gate-effects.png'),width=1400,height=850,res=160);par(mar=c(7,5,3,1));plot(NA,xlim=c(.5,4.5),ylim=range(c(0,young$lower,young$upper,old$lower,old$upper)),xaxt='n',xlab='',ylab='Change in threshold effect (individuals)',main='Age-specific reproduction interventions');abline(h=0,lty=2,col='gray50');axis(1,at=1:4,labels=c('48 founders\nSame ages','96 founders\nSame ages','48 founders\nStaggered ages','96 founders\nStaggered ages'),tick=FALSE,line=.2);for(j in 1:2){v<-list(young,old)[[j]];x<-1:4+c(-.09,.09)[j];col<-c('#2166ac','#b2182b')[j];arrows(x,v$lower,x,v$upper,angle=90,code=3,length=.04,col=col);points(x,v$mean,pch=c(16,17)[j],col=col)};legend('bottomleft',legend=c('Reduce under-50 reproduction','Reduce 150+ reproduction'),pch=c(16,17),col=c('#2166ac','#b2182b'),bty='n');mtext('Gate versus sham; points and 95% paired intervals',side=1,line=5,cex=.8);dev.off()
